{
  "compilerOptions": {
    "jsx": "react-jsx",
    "jsxImportSource": "@pyreon/react-compat"
  }
}

import { nativeCompat } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'

// A converted component inside a compat app: it runs once.
export const Likes = nativeCompat(function Likes() {
  const likes = signal(0)
  return (
    <button onClick={() => likes.update((n) => n + 1)}>
      {() => `${likes()} likes`}
    </button>
  )
})

